ALTER TABLE "credit_ledger" ADD CONSTRAINT "credit_ledger_kind_check" CHECK ("credit_ledger"."kind" in ('grant', 'reserve', 'commit', 'refund', 'adjust'));--> statement-breakpoint
ALTER TABLE "credit_ledger" ADD CONSTRAINT "credit_ledger_amount_sign_check" CHECK ((("credit_ledger"."kind" = 'grant' and "credit_ledger"."amount" > 0) or ("credit_ledger"."kind" = 'refund' and "credit_ledger"."amount" > 0) or ("credit_ledger"."kind" = 'reserve' and "credit_ledger"."amount" < 0) or ("credit_ledger"."kind" = 'commit' and "credit_ledger"."amount" <= 0) or "credit_ledger"."kind" = 'adjust'));--> statement-breakpoint
ALTER TABLE "credit_ledger" ADD CONSTRAINT "credit_ledger_amount_ceiling_check" CHECK ("credit_ledger"."amount" <= 1000000000000000 and "credit_ledger"."amount" >= -1000000000000000);